import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.mRCPFc5l.js";const s="/assets/settings-menu.B7dZhij3.png",i="/assets/about-diagnostics.B7Rq-Pbi.png",g=JSON.parse('{"title":"Settings and Help","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/08-settings-and-help.md","filePath":"en_US/08-settings-and-help.md"}'),r={name:"en_US/08-settings-and-help.md"};function l(c,e,d,h,p,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="settings-and-help" tabindex="-1">Settings and Help <a class="header-anchor" href="#settings-and-help" aria-label="Permalink to &quot;Settings and Help&quot;">​</a></h1><p>Adjust the interface, manage shared tools, update the app, and troubleshoot common problems.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Change UI language, font, text size, and overall scale.</li><li>Show hidden columns and manage spelling/translation presets.</li><li>Check for updates, open license management, and clear caches.</li><li>View shortcuts, versions, third-party notices, and diagnostics.</li></ul><h2 id="switch-the-interface-language" tabindex="-1">Switch the interface language <a class="header-anchor" href="#switch-the-interface-language" aria-label="Permalink to &quot;Switch the interface language&quot;">​</a></h2><p>Open <strong>Settings → UI Language</strong> and choose <strong>English</strong> or <strong>中文</strong>. The preference is stored locally and restored at the next launch. Missing localized text may fall back to English; internal translation keys should not appear in a normal UI.</p><h2 id="adjust-fonts-and-size" tabindex="-1">Adjust fonts and size <a class="header-anchor" href="#adjust-fonts-and-size" aria-label="Permalink to &quot;Adjust fonts and size&quot;">​</a></h2><ul><li><strong>Editor Font</strong> changes grid text.</li><li><strong>Grid Font Size</strong> changes subtitle-cell text, with a 12px minimum.</li><li><strong>UI Size</strong> scales the whole interface from 50% to 150% in 5% steps.</li></ul><p><img src="'+s+'" alt="Settings menu with language, font, size, and tool entries"></p><p>For a small window or high-DPI screen, lower UI Size or drag the grid/video divider. 960×600 is the recommended minimum for the full editing experience; 840×480 keeps core controls reachable for emergency use.</p><h2 id="show-or-hide-grid-columns" tabindex="-1">Show or hide grid columns <a class="header-anchor" href="#show-or-hide-grid-columns" aria-label="Permalink to &quot;Show or hide grid columns&quot;">​</a></h2><p>Enable <strong>Show Hidden Columns</strong> to display metadata columns. Turning it off changes visibility only and does not delete data. <strong>Reset View</strong> restores column widths and layout.</p><h2 id="manage-spellcheck" tabindex="-1">Manage spellcheck <a class="header-anchor" href="#manage-spellcheck" aria-label="Permalink to &quot;Manage spellcheck&quot;">​</a></h2><p>Use <strong>Spellcheck translation</strong> to enable/disable scanning. Open <strong>Dictionaries</strong> to install, refresh, and select Hunspell-format dictionaries, ignored words, and user words. See <a href="./05-quality-checks.html#install-and-switch-spelling-dictionaries">Quality Checks</a>.</p><h2 id="manage-machine-translation-presets" tabindex="-1">Manage machine-translation presets <a class="header-anchor" href="#manage-machine-translation-presets" aria-label="Permalink to &quot;Manage machine-translation presets&quot;">​</a></h2><p><strong>Machine Translation Providers</strong> manages connections, models, capabilities, and network settings. <strong>Machine Translation Prompts</strong> manages reusable translation guidance. See <a href="./06-machine-translation.html">Machine Translation</a>.</p><h2 id="check-and-install-updates" tabindex="-1">Check and install updates <a class="header-anchor" href="#check-and-install-updates" aria-label="Permalink to &quot;Check and install updates&quot;">​</a></h2><p>Windows and macOS have separate release channels and may have different latest versions. The app receives updates for its own system and architecture. Save projects before installing. Full cross-version upgrades for the Mac test build are still undergoing validation; if an update fails, download the appropriate installer from your distributor.</p><p>Click <strong>Check for Updates</strong>. If an update is available, review the old/new version, choose <strong>Later</strong> or <strong>Install Update</strong>, and wait for download/install progress. The app restarts after successful installation. A manual failure displays an error; keep the current version and project files intact while troubleshooting.</p><h2 id="open-license-management" tabindex="-1">Open license management <a class="header-anchor" href="#open-license-management" aria-label="Permalink to &quot;Open license management&quot;">​</a></h2><p>Choose <strong>Settings → License</strong> to view status, request a license, or remove one. See <a href="./09-license-management.html">License Management</a> for the full workflow.</p><h2 id="clear-caches-and-restart" tabindex="-1">Clear caches and restart <a class="header-anchor" href="#clear-caches-and-restart" aria-label="Permalink to &quot;Clear caches and restart&quot;">​</a></h2><p><strong>Clear Cache and Restart</strong> asks for confirmation and warns again when unsaved changes exist. It clears app-owned UI/session caches and stored file-handle information, then reloads. It does not delete <code>project.json</code>, <code>workspace.csv</code>, project drafts on disk, or project folders. Save important work first.</p><h2 id="view-keyboard-shortcuts" tabindex="-1">View keyboard shortcuts <a class="header-anchor" href="#view-keyboard-shortcuts" aria-label="Permalink to &quot;View keyboard shortcuts&quot;">​</a></h2><p>Choose <strong>Keyboard Shortcuts</strong> or press <code>?</code>. The dialog groups editing, grid, and video commands. See <a href="./01-getting-started.html#view-shortcuts-and-help">Getting Started</a> for a quick table.</p><h2 id="view-version-and-third-party-notices" tabindex="-1">View version and third-party notices <a class="header-anchor" href="#view-version-and-third-party-notices" aria-label="Permalink to &quot;View version and third-party notices&quot;">​</a></h2><p>Open <strong>About GridSubStudio</strong> to see the app version, runtime summary, third-party components/licenses, and temporary diagnostics controls.</p><h2 id="enable-and-export-temporary-diagnostics" tabindex="-1">Enable and export temporary diagnostics <a class="header-anchor" href="#enable-and-export-temporary-diagnostics" aria-label="Permalink to &quot;Enable and export temporary diagnostics&quot;">​</a></h2><ol><li>Open <strong>About GridSubStudio</strong>.</li><li>Enable <strong>temporary diagnostics</strong>.</li><li>Reproduce the focus, selection, playback, or scrolling issue.</li><li>Click <strong>Export diagnostics</strong>.</li></ol><p><img src="'+i+'" alt="Temporary diagnostics controls in About GridSubStudio"></p><p>Diagnostics keep a limited in-memory state trace for the current workspace and do not record subtitle text. They clear when the workspace changes, closes, or diagnostics are disabled.</p><h2 id="troubleshoot-common-problems" tabindex="-1">Troubleshoot common problems <a class="header-anchor" href="#troubleshoot-common-problems" aria-label="Permalink to &quot;Troubleshoot common problems&quot;">​</a></h2><h3 id="macos-blocks-the-first-launch" tabindex="-1">macOS blocks the first launch <a class="header-anchor" href="#macos-blocks-the-first-launch" aria-label="Permalink to &quot;macOS blocks the first launch&quot;">​</a></h3><p>The Mac test build is not notarized. Follow the <a href="./01-getting-started.html#first-launch-on-macos-bypass-the-gatekeeper-block">Gatekeeper exception steps</a> for this app. An exception does not fix an unsupported OS or architecture; check installation requirements first.</p><h3 id="project-setup-cannot-be-confirmed" tabindex="-1">Project Setup cannot be confirmed <a class="header-anchor" href="#project-setup-cannot-be-confirmed" aria-label="Permalink to &quot;Project Setup cannot be confirmed&quot;">​</a></h3><p>Wait for imports, then resolve missing episodes, normalized duplicate episodes, missing resources, ambiguous matches, and import errors. Low confidence alone requires review but does not block confirmation.</p><h3 id="project-is-open-in-another-window" tabindex="-1">Project is open in another window <a class="header-anchor" href="#project-is-open-in-another-window" aria-label="Permalink to &quot;Project is open in another window&quot;">​</a></h3><p>One project cannot be edited by two active instances. Close it normally in the original window. Different projects may be open in separate windows.</p><h3 id="video-is-missing" tabindex="-1">Video is missing <a class="header-anchor" href="#video-is-missing" aria-label="Permalink to &quot;Video is missing&quot;">​</a></h3><p>Subtitle editing remains available. Reopen <strong>Project Setup</strong>, import the video, and correct episode mapping.</p><h3 id="spellcheck-is-unavailable" tabindex="-1">Spellcheck is unavailable <a class="header-anchor" href="#spellcheck-is-unavailable" aria-label="Permalink to &quot;Spellcheck is unavailable&quot;">​</a></h3><p>Confirm a direct dictionary subfolder contains matching <code>index.aff</code> and <code>index.dic</code>, click <strong>Refresh</strong>, and select it. See the <a href="./05-quality-checks.html#install-and-switch-spelling-dictionaries">dictionary installation guide</a>.</p><h3 id="machine-translation-cannot-run" tabindex="-1">Machine translation cannot run <a class="header-anchor" href="#machine-translation-cannot-run" aria-label="Permalink to &quot;Machine translation cannot run&quot;">​</a></h3><p>Use project mode, import subtitles, enable a provider, enter a valid episode scope, and verify Base URL, API key, model, and proxy.</p><h3 id="subtitles-cannot-be-exported" tabindex="-1">Subtitles cannot be exported <a class="header-anchor" href="#subtitles-cannot-be-exported" aria-label="Permalink to &quot;Subtitles cannot be exported&quot;">​</a></h3><p>Check license status, available rows, ASS template, filename conflicts, and output-folder permissions. See <a href="./09-license-management.html#troubleshoot-license-problems">License troubleshooting</a>.</p><h3 id="update-failed" tabindex="-1">Update failed <a class="header-anchor" href="#update-failed" aria-label="Permalink to &quot;Update failed&quot;">​</a></h3><p>Check network access and retry manually. Keep the installed version and project files; record the error and export diagnostics when support requests them.</p>',48)])])}const b=a(r,[["render",l]]);export{g as __pageData,b as default};
